// mouse: left = attack, right = block, the pointer aims
const scrEl=$('screen');
// Kliknięcie/dotyk świata działa także bez panelu sterowania dotykowego.
let worldTap=null,selectedNpcAction=null;
function worldTapTarget(e,selectNpc=false){
 if(!S||S.phase!=='play'||S.paused||S.intro||S.dialog||S.choosing||S.shop||!pl||pl.dead||e.target.closest('.overlay,button,input,summary,#activeSkillHud')||(!selectNpc&&e.target.closest('#touch')))return null;
 const candidates=W.npcs.filter(n=>!n.lure&&npcTalk(n)&&(selectNpc||Math.hypot(pl.x-n.x,pl.y-n.y)<30)).map(n=>({target:n,kind:'npc'}));
 const fire=selectNpc?null:nearPowerFire();if(fire)candidates.push({target:fire,kind:'fire'});
 const merchant=selectNpc?null:nearMerchant();if(merchant)candidates.push({target:merchant,kind:'merchant'});
 const exit=selectNpc?null:nearExit();if(exit)candidates.push({target:exit,kind:'exit'});
 const r=lrect(scrEl);let best=null,bestD=80;
 for(const c of candidates){const n=c.target;for(const height of [0,1,2]){V.set(n.x/16,height,n.y/16).project(cam);if(V.z< -1||V.z>1)continue;
 const d=Math.hypot(e.clientX-(r.left+(V.x+1)/2*r.width),e.clientY-(r.top+(1-V.y)/2*r.height));if(d<bestD){bestD=d;best=c}}}return best;
}
function useWorldTap(c){mouseL=false;talkPress=false;
 if(c.kind==='npc')openDialog(c.target);else if(c.kind==='fire')activatePowerFire(c.target);else if(c.kind==='merchant')openShop();else useExit(c.target);
}
// Ctrl+LPM wybiera NPC niezależnie od panelu dotyku i zwykłego klikania.
function selectNpcWithPointer(e){
 if(!e.ctrlKey||e.button!==0||!scrEl.contains(e.target))return;
 const hit=worldTapTarget(e,true);if(!hit)return;
 e.preventDefault();e.stopImmediatePropagation();worldTap=null;mouseL=false;
 selectedNpcAction={npc:hit.target,state:S};
 if(Math.hypot(pl.x-hit.target.x,pl.y-hit.target.y)<30){selectedNpcAction=null;useWorldTap(hit)}
 else say((EN?'Selected: ':'Wybrano: ')+hit.target.name+(EN?'. Walk closer to start talking.':'. Podejdź, aby rozpocząć rozmowę.'));
}
addEventListener('pointerdown',selectNpcWithPointer,true);
addEventListener('mousedown',e=>{if(e.ctrlKey){mouseL=false;selectNpcWithPointer(e)}},true);
scrEl.addEventListener('pointerdown',e=>{
 if(e.ctrlKey||e.button!==0||!e.isPrimary||!worldTapTarget(e))return;
 worldTap={id:e.pointerId,x:e.clientX,y:e.clientY,t:performance.now(),hit:worldTapTarget(e)};
 mouseL=false;e.preventDefault();
},true);
scrEl.addEventListener('pointerup',e=>{
 const d=worldTap;if(!d||d.id!==e.pointerId)return;worldTap=null;
 const hit=worldTapTarget(e);
 if(performance.now()-d.t<=450&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<=16&&hit&&hit.kind===d.hit.kind&&hit.target.x===d.hit.target.x&&hit.target.y===d.hit.target.y){useWorldTap(hit);e.preventDefault()}
},true);
addEventListener('pointercancel',()=>{worldTap=null});addEventListener('pointerup',()=>{worldTap=null});
scrEl.addEventListener('mousedown',e=>{if(!S||S.phase!=='play'||S.paused||e.ctrlKey||worldTap||e.target.closest('.overlay'))return;if(e.button===0)mouseL=true;if(e.button===2)mouseR=true});
addEventListener('mouseup',e=>{if(e.button===0)mouseL=false;if(e.button===2)mouseR=false});
scrEl.addEventListener('contextmenu',e=>{if(S&&S.phase==='play')e.preventDefault()});
scrEl.addEventListener('mousemove',e=>{const r=scrEl.getBoundingClientRect();mouseX=e.clientX-r.left;mouseY=e.clientY-r.top;mouseT=clock});

// The game follows the device: landscape or portrait, never turned by code. It fills the whole window by widening
// the view: at least the old 16:9 picture height is visible in landscape; in portrait the visible width equals that
// height and the extra room goes up and down. Wider than 2.4:1 (ultrawide) gets thin side bars instead.
var ROT=false;// fit() can run before this line, so its numbers are literals: max aspect 2.4, base vertical FOV 24°
function lp(x,y){return [x,y]}
function lrect(el){return el.getBoundingClientRect()}
function fit(){const st=$('stage'),r=st.getBoundingClientRect();let w=Math.max(1,Math.floor(r.width)),h=Math.max(1,Math.floor(r.height));if(w/h>2.4)w=Math.floor(h*2.4);const s=Math.min(w/320,h/180),port=h>w;
  const scr=$('screen');scr.style.width=w+'px';scr.style.height=h+'px';scr.classList.toggle('port',port);document.documentElement.classList.toggle('port',port);scr.style.fontSize=(Math.max(10,s*5.2)*SETT.fts/100)+'px';
  renderer.setPixelRatio(Math.min(GFX.dpr,window.devicePixelRatio||1));renderer.setSize(w,h,false);FIT.w=w;FIT.h=h;rtApply();
  
  cam.aspect=w/h;cam.fov=2*Math.atan(Math.tan(12*Math.PI/180)/Math.min(1,w/h))*180/Math.PI;cam.updateProjectionMatrix()}
addEventListener('resize',fit);fit();
// iPhone (above all as a home-screen app) often reports the new size late after rotating, so fit again on every signal and a moment later
const refit=()=>{fit();try{if(matchMedia('(orientation:portrait) and (pointer:coarse)').matches&&S&&S.phase==='play'&&!S.paused)togglePause(true)}catch(e){}setTimeout(fit,120);setTimeout(fit,400);setTimeout(fit,900)};
addEventListener('orientationchange',refit);addEventListener('pageshow',refit);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refit()});
if(window.visualViewport)visualViewport.addEventListener('resize',fit);
if(window.ResizeObserver)new ResizeObserver(()=>fit()).observe($('stage'));
if(window.screen&&screen.orientation&&screen.orientation.addEventListener)screen.orientation.addEventListener('change',refit);

// ---- TRENER (tryb testera, odblokowany kodem; w grze tylko hash SHA-256 kodu, nie sam kod) ----
const TRN_H='893bdb3236d2c8112d0ac06e839655454a79b986f59b67bebb6a65fc363dead3';
function trnSave(){try{localStorage.setItem('pn_trainer',JSON.stringify(TRN))}catch(e){}}
async function trnHash(t){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function trnAsh(){EMB.e+=500;saveEmb();play('coin',0);if(S&&S.phase==='play')ftInfo(EN?'+500 Ashes':'+500 Popiołów')}
function trnKill(e){if(!e||e.dead)return;e.inv=0;damageEnemy(e,e.hp+1e7,0,0,0,'trn')}
function trnNext(){if(!S||S.dg)return;
  if(S.stage==='p1'){S.t=Math.max(S.t,BREAK_AT);return}
  if(S.stage==='collector'){if(S.collT>0)S.collT=.01;else{const b=[S.collector,S.leszy].find(x=>x&&!x.dead);if(b)trnKill(b)}return}
  if(S.stage==='break'){if(S.merchant)leaveMerchant();else S.stage='p2';return}
  if(S.stage==='p2')S.t=Math.max(S.t,NIGHT)}
function trnSpawn(type){if(!S||!ET[type]||pl.dead)return;const a=Math.random()*6.283,x=pl.x+Math.cos(a)*48,y=pl.y+Math.sin(a)*32;
  const boss=BIG.has(type)||type==='collector',hp=boss?Math.round(bossHealth(type)*(BIG.has(type)?BOSS_HP_MUL:1)):0;
  const e=spawnEnemy(type,x,y,boss?{rise:1,hp,max:hp,stolen:0}:{rise:.5});if(e&&BIG.has(type)&&e.spd)e.spd*=BOSS_SPD_MUL}
function trnFill(){const sel=$('trnType');if(!sel||!TRN.on)return;const cur=sel.value,ks=Object.keys(ET).filter(k=>A&&A[k]);
  sel.innerHTML=ks.map(k=>`<option value="${k}">${(ENAME[k]||k)}${BIG.has(k)||k==='collector'?' ★':''}</option>`).join('');if(ks.includes(cur))sel.value=cur;trnLabels()}
function trnLabels(){const g=$('trnGod'),o=$('trnOhk');if(g)g.textContent=(EN?'Invincible: ':'Nieśmiertelność: ')+(TRN.god?(EN?'ON':'WŁ.'):(EN?'off':'wył.'));if(o)o.textContent=(EN?'One-hit kill: ':'Zabijanie jednym ciosem: ')+(TRN.ohk?(EN?'ON':'WŁ.'):(EN?'off':'wył.'))}
// 10.11.2026: Options > Controls > Keyboard: rows to rebind the play keys
function kbUi(){const host=$('sub-kb');if(!host)return;let b=$('kbBind');if(!b){b=document.createElement('div');b.id='kbBind';host.appendChild(b)}
  if(!$('kbCss')){const st=document.createElement('style');st.id='kbCss';st.textContent='#kbBind .kbgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.45em 1.6em;margin:.6em 0}#kbBind .kbrow{display:flex;align-items:center;justify-content:space-between;gap:.8em}#kbBind .kbb{min-width:8.5em;margin:0;text-align:center;justify-content:center}#kbBind .kbb.on{outline:2px solid #e8c25a;color:#ffe2a2}@media (max-width:700px){#kbBind .kbgrid{grid-template-columns:1fr}}';document.head.appendChild(st)}
  const N=EN?{up:'Move up',down:'Move down',left:'Move left',right:'Move right',atk:'Attack (hold: heavy)',blk:'Block and parry',heavy:'Heavy attack',roll:'Dodge',s1:'Skill 1',s2:'Skill 2',s3:'Skill 3',s4:'Skill 4',talk:'Talk / use'}:{up:'Ruch w górę',down:'Ruch w dół',left:'Ruch w lewo',right:'Ruch w prawo',atk:'Cios (przytrzymaj: silny)',blk:'Blok i parowanie',heavy:'Silny atak',roll:'Unik',s1:'Umiejętność 1',s2:'Umiejętność 2',s3:'Umiejętność 3',s4:'Umiejętność 4',talk:'Rozmowa / użycie'};
  b.innerHTML=`<div class="opsep sm" aria-hidden="true"></div><h3 class="sth">${EN?'Your own keys':'Własne klawisze'}</h3><p class="figcap">${EN?'Click an action, then press the new key. Esc cancels. A key already in use swaps places. Arrow keys always move; Esc, P and the digits stay fixed. The diagram above and the hints show the default keys.':'Kliknij czynność, potem naciśnij nowy klawisz. Esc anuluje. Zajęty klawisz zamienia się miejscami. Strzałki zawsze poruszają postacią; Esc, P i cyfry są stałe. Schemat powyżej i podpowiedzi pokazują klawisze domyślne.'}</p><div class="kbgrid">`+Object.keys(KB_DEF).map(a=>`<div class="kbrow"><span>${N[a]}</span><button type="button" class="go alt kbb${KB.wait===a?' on':''}" data-a="${a}"></button></div>`).join('')+`</div><div class="btnrow"><button type="button" class="go alt" id="kbReset">${EN?'Restore default keys':'Przywróć domyślne klawisze'}</button></div>`;
  for(const x of b.querySelectorAll('.kbb')){const a=x.dataset.a;x.textContent=KB.wait===a?(EN?'Press a key…':'Naciśnij klawisz…'):kbName(KB.map[a]);x.addEventListener('click',()=>{KB.wait=KB.wait===a?null:a;kbUi();const n=$('kbBind').querySelector('.kbb[data-a="'+a+'"]');n&&n.focus()})}
  $('kbReset').addEventListener('click',()=>{KB.map={...KB_DEF};KB.wait=null;kbSave();kbUi()})}
addEventListener('keydown',e=>{if(!KB.wait)return;e.preventDefault();e.stopImmediatePropagation();const k=e.key.toLowerCase(),a=KB.wait;KB.wait=null;if(k!=='escape'&&kbOk(k)&&(k!=='enter'||a==='talk')){const o=Object.keys(KB.map).find(x=>KB.map[x]===k);if(o&&o!==a)KB.map[o]=KB.map[a];KB.map[a]=k;kbSave()}kbUi();const n=$('kbBind')&&$('kbBind').querySelector('.kbb[data-a="'+a+'"]');n&&n.focus()},true);
try{kbUi()}catch(e){quietErr('kbUi',e)}
// 10.11.2026: training ground (S.train): chapter I without the night clock, spawns, death or saved progress;
// enemies are summoned from the pause menu
function startTraining(){const go=()=>{$('manual').hidden=true;openPrep(1);PREP.curses=[];PREP.weekly=null;PREP.daily=null;PREP.endless=false;PREP.train=true;renderPrep();beginRun()};return groupReady(1)?go():waitChapter(1,go,$('trainBtn'))}
function trainBox(){const old=$('trainBox');if(old)old.remove();if(!S||!S.train||!S.paused)return;const at=$('skillLoadout');if(!at)return;
  const B=(id,t)=>`<button class="go alt" type="button" id="${id}">${t}</button>`;
  at.insertAdjacentHTML('beforebegin',`<div id="trainBox" class="pbox trnbox"><h3 class="sth">${EN?'Training ground':'Plac ćwiczeń'}</h3><p class="figcap">${EN?'You cannot die here and nothing is saved. Summon an enemy and practise parrying, dodging and skills.':'Tutaj nie możesz zginąć i nic się nie zapisuje. Przywołaj wroga i ćwicz parowanie, uniki i umiejętności.'}</p><div class="btnrow"><select id="trainType" aria-label="${EN?'Enemy':'Wróg'}"></select>${B('trainSpawn',EN?'Summon':'Przywołaj')}${B('trainClear',EN?'Remove all':'Usuń wszystkich')}${B('trainLvl',EN?'+1 night level':'+1 poziom nocy')}</div></div>`);
  const sel=$('trainType'),ks=Object.keys(ET).filter(k=>A[k]&&ENAME[k]&&k!=='glizzard');for(const k of ks){const o=document.createElement('option');o.value=k;o.textContent=ENAME[k]+(BIG.has(k)||k==='collector'?' ★':'');sel.appendChild(o)}if(ks.includes(S.trainSel))sel.value=S.trainSel;
  $('trainSpawn').addEventListener('click',()=>{S.trainSel=sel.value;trnSpawn(sel.value);togglePause(false)});
  $('trainClear').addEventListener('click',()=>{for(const e of S.enemies.slice())trnKill(e);togglePause(false)});
  $('trainLvl').addEventListener('click',()=>{S.xp=S.need;while(S.xp>=S.need){S.xp-=S.need;S.lvl++;S.need=xpNeed(S.lvl);S.pendLv++}play('level',0);togglePause(false)})}
function trnBuild(){const old=$('trnBox');if(old)old.remove();if(!TRN.on)return;
  const B=(id,pl_,en)=>`<button class="go alt" type="button" id="${id}">${EN?en:pl_}</button>`;
  $('pauseKeys').insertAdjacentHTML('afterend',`<div id="trnBox" class="pbox trnbox"><h3 class="sth">${EN?'Trainer':'Trener'}</h3>
<div class="btnrow">${B('trnGod','','')}${B('trnOhk','','')}</div>
<div class="btnrow">${B('trnLvl','+1 poziom','+1 level')}${B('trnCoin','+100 monet','+100 coins')}${B('trnAsh','+500 Popiołów','+500 Ashes')}${B('trnHeal','Pełne zdrowie','Full health')}</div>
<div class="btnrow"><select id="trnType" aria-label="${EN?'Enemy':'Wróg'}"></select>${B('trnSpawn','Przywołaj','Summon')}</div>
<div class="btnrow">${B('trnKillAll','Zabij wszystkich','Kill all')}${B('trnNextSt','Następny etap','Next stage')}</div></div>`);
  const on=(id,f)=>$(id).addEventListener('click',f);
  on('trnGod',()=>{TRN.god=!TRN.god;trnSave();trnLabels()});
  on('trnOhk',()=>{TRN.ohk=!TRN.ohk;trnSave();trnLabels()});
  on('trnLvl',()=>{if(!S)return;S.xp=S.need;while(S.xp>=S.need){S.xp-=S.need;S.lvl++;S.need=xpNeed(S.lvl);S.pendLv++}play('level',0);togglePause(false)});
  on('trnAsh',trnAsh);
  on('trnCoin',()=>{if(!S)return;S.coins+=100;play('coin',0)});
  on('trnHeal',()=>{if(!S||pl.dead)return;pl.hp=pl.max;pl.sta=pl.staMax;pl.mana=pl.manaMax;play('heal',0)});
  on('trnSpawn',()=>{trnSpawn($('trnType').value);togglePause(false)});
  on('trnKillAll',()=>{if(!S)return;for(const e of S.enemies.slice())trnKill(e);togglePause(false)});
  on('trnNextSt',()=>{trnNext();togglePause(false)});
  trnFill()}
function trnOpts(){const old=$('trnOpt');if(old)old.remove();
  $('repeatTut').insertAdjacentHTML('afterend',`<div id="trnOpt"><div class="opsep sm" aria-hidden="true"></div><h3 class="sth">${EN?'Tester mode':'Tryb testera'}</h3>`+
  (TRN.on?`<p class="figcap">${EN?'The trainer is unlocked: you will find it in the pause menu.':'Trener odblokowany: znajdziesz go w menu pauzy.'}</p><div class="btnrow"><button class="go alt" id="trnAsh2" type="button">${EN?'+500 Ashes':'+500 Popiołów'}</button><button class="go alt" id="trnOff" type="button">${EN?'Turn tester mode off':'Wyłącz tryb testera'}</button></div>`
  :`<div class="btnrow"><input type="password" id="trnCode" autocomplete="off" aria-label="${EN?'Tester code':'Kod testera'}" placeholder="${EN?'Tester code':'Kod testera'}" style="font:inherit;font-size:1.1em;padding:.3em .5em;min-width:0;flex:1;max-width:12em;background:#1b1416;color:var(--bone);border:1px solid #6b4b45;border-radius:.3em"><button class="go alt" id="trnBtn" type="button">${EN?'Unlock':'Odblokuj'}</button></div><p class="figcap" id="trnCap">${EN?'A trainer console for testing mechanics. Requires a code.':'Konsola trenera do testowania mechanik. Wymaga kodu.'}</p>`)+`</div>`);
  if(TRN.on){$('trnAsh2').addEventListener('click',()=>{trnAsh();$('trnAsh2').textContent=(EN?'+500 Ashes · now ':'+500 Popiołów · masz ')+EMB.e});$('trnOff').addEventListener('click',()=>{TRN.on=TRN.god=TRN.ohk=false;trnSave();trnBuild();trnOpts()});return}
  const go=async()=>{const v=$('trnCode').value.trim().toLowerCase();if(!v)return;let h='';try{h=await trnHash(v)}catch(e){}
    if(h===TRN_H){TRN.on=true;trnSave();trnBuild();trnOpts();play('bless',0)}else{$('trnCap').textContent=EN?'Wrong code.':'Zły kod.';play('empty',0)}};
  $('trnBtn').addEventListener('click',go);$('trnCode').addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter')go()})}
trnOpts();trnBuild();

